from collections import defaultdict
from typing import List

def empty_shelf(bookshelf: List[List[int]], k: int) -> int:
    cells_by_type = defaultdict(list)
    for r, row in enumerate(bookshelf):
        for c, t in enumerate(row):
            if t:
                cells_by_type[t].append((r, c))

    def min_turns(cells):
        # 选中的书（中心）必须两两不同行、不同列，且它们的行列要覆盖该类型的所有书：
        # 即二分图（行-列，每本书一条边）上的“最小极大匹配”。用迭代加深搜索求精确值。
        def dfs(rows, cols, left):
            target = next(((r, c) for r, c in cells if r not in rows and c not in cols), None)
            if target is None:
                return True
            if left == 0:
                return False
            r0, c0 = target
            # 要覆盖 target，必须选一本与它同行或同列、且行列都未被占用的书
            for r, c in cells:
                if (r == r0 or c == c0) and r not in rows and c not in cols:
                    if dfs(rows | {r}, cols | {c}, left - 1):
                        return True
            return False

        # ponytail: 最小极大匹配是 NP 难问题，搜索最坏是指数级；书架接近 100x100 且同类型书很多时需要剪枝或近似
        limit = 1
        while not dfs(frozenset(), frozenset(), limit):
            limit += 1
        return limit

    return sum(min_turns(cells) for cells in cells_by_type.values())
